mapper.select:
select count(distinct instance_id) from icd_instance_audit
where
    delete_flag = 0

    and code = #{userId}


    and application_id = #{applicationId}

select count(distinct i.id) from icd_instance_task t
inner join icd_process_instance i on t.instance_id = i.id and t.delete_flag = 0 and i.stage = 2
where i.delete_flag = 0

    and t.user_id = #{userId}


    and i.application_id = #{applicationId}

select count(distinct i.id) from icd_instance_task t
inner join icd_process_instance i on t.instance_id = i.id and t.delete_flag = 0 and
(t.task_type = 2 or t.task_type = 4 or t.task_type = 5)
where i.delete_flag = 0

    and t.user_id = #{userId}


    and i.application_id = #{applicationId}

select count(1) from icd_process_instance where delete_flag = 0 and task_id != '0'

    and creator = #{userId}


    and application_id = #{applicationId}

select count(1) from icd_process_instance
where delete_flag = 0
and task_id != '0'

    and application_id = #{applicationId}


    and stage in

        #{stage}



     and create_time >= #{startTime}
    and create_time <= #{endTime}
